from pathlib import Path
import re
for p in Path('/docs').glob('*.txt'):
 s=p.read_text()
 if re.search(r'general\\s+agreement',s,re.I):
  for m in re.finditer(r'general\\s+agreement',s,re.I):
   print(p.name, s[max(0,m.start()-300):m.end()+600])
